\set ON_ERROR_STOP on
set client_min_messages=warning;
create function pg_temp.recipe() returns jsonb language sql immutable as $$select '{"version":"sf-sdxl-recommended-v1","mode":"recommended","settings":{"resolution":[1024,1024],"enable_bucket":true,"min_bucket_reso":512,"max_bucket_reso":1024,"bucket_reso_steps":64,"train_batch_size":1,"learning_rate":0.0001,"network_module":"networks.lora","network_dim":64,"network_alpha":32,"mixed_precision":"fp16","gradient_checkpointing":true,"save_model_as":"safetensors","save_every_n_steps":200,"target_effective_samples":1200,"caption_extension":".txt","caption_model":"Salesforce/blip-image-captioning-base","trigger_suffix":"woman"}}'::jsonb$$;
create function pg_temp.payload(job uuid,lora uuid,snapshot jsonb,decision jsonb,ids jsonb) returns jsonb language sql stable as $$select jsonb_build_object('identity_id',lora::text,'dataset_doctor_job_id',job::text,'dataset_reference',jsonb_build_object('bucket','datasets','prefix','final/a'),'dataset_snapshot',snapshot,'dataset_selection',jsonb_build_object('image_ids',ids,'image_count',jsonb_array_length(ids)),'dataset_training_decision',decision,'trainer_recipe',pg_temp.recipe())$$;
create function pg_temp.expect_error(expected text,statement text) returns void language plpgsql as $$begin execute statement;raise exception 'EXPECTED_FAILURE_NOT_RAISED:%',expected;exception when others then if sqlerrm not like expected||'%' then raise exception 'EXPECTED_%,GOT_%',expected,sqlerrm;end if;end$$;

do $$declare role_name text;t text;fn regprocedure;begin
 foreach t in array array['dataset_doctor_training_decision_prompts','dataset_doctor_training_decision_receipts'] loop foreach role_name in array array['anon','authenticated','service_role'] loop assert not has_table_privilege(role_name,'public.'||t,'select');assert not has_table_privilege(role_name,'public.'||t,'insert');assert not has_table_privilege(role_name,'public.'||t,'update');assert not has_table_privilege(role_name,'public.'||t,'delete');end loop;assert not exists(select 1 from information_schema.role_table_grants where table_schema='public' and table_name=t and grantee='PUBLIC');end loop;
 foreach fn in array array['public.prepare_dataset_training_decision_prompt(uuid,uuid,uuid,text,uuid[])'::regprocedure,'public.record_dataset_training_decision_receipt(uuid,uuid,uuid,text)'::regprocedure,'public.validate_dataset_training_decision_receipt(uuid,uuid,uuid,uuid)'::regprocedure] loop assert has_function_privilege('service_role',fn,'execute');assert not has_function_privilege('anon',fn,'execute');assert not has_function_privilege('authenticated',fn,'execute');assert not exists(select 1 from aclexplode((select proacl from pg_proc where oid=fn))a where grantee=0 and privilege_type='EXECUTE');end loop;
 assert not has_function_privilege('service_role','public.link_dataset_training_decision_receipt(uuid,uuid)','execute');
end$$;

