create temporary table receipt_one as select * from public.record_dataset_training_decision_receipt('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','decision-one');
do $$declare r public.dataset_doctor_training_decision_receipts;begin select x.* into r from public.dataset_doctor_training_decision_receipts x join receipt_one t on t.receipt_id=x.id;assert r.shown_at=(select shown_at from prompt_one);assert r.decided_at>=r.shown_at;assert (select receipt_id from public.record_dataset_training_decision_receipt(r.user_id,r.lora_id,r.dataset_doctor_job_id,r.decision_idempotency_key))=r.id;begin update public.dataset_doctor_training_decision_receipts set warning_snapshot='{}';raise exception 'mutable';exception when others then assert sqlerrm='DATASET_TRAINING_DECISION_EVIDENCE_IMMUTABLE';end;end$$;

-- Ready submission and fabricated ready decision.
create temporary table ready_job as select job_id from public.submit_trainer_compute_job('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000002','ready-job',repeat('a',64),pg_temp.payload('30000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002',(select summary from public.dataset_doctor_jobs where id='30000000-0000-4000-8000-000000000002'),'null',(select public.dataset_training_final_selection('30000000-0000-4000-8000-000000000002'))),'standard','datasets','final/a');
select pg_temp.expect_error('DATASET_TRAINING_DECISION_INVALID',format('select * from public.submit_trainer_compute_job(%L,%L,%L,%L,%L::jsonb,%L,%L,%L)','10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000002','ready-fake',repeat('b',64),pg_temp.payload('30000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002',(select summary from public.dataset_doctor_jobs where id='30000000-0000-4000-8000-000000000002'),'{"receipt_id":"40000000-0000-4000-8000-000000000001"}',public.dataset_training_final_selection('30000000-0000-4000-8000-000000000002'))::text,'standard','datasets','final/a'));
-- Not-ready submission requires and links exact receipt.
select pg_temp.expect_error('DATASET_TRAINING_DECISION_REQUIRED',format('select * from public.submit_trainer_compute_job(%L,%L,%L,%L,%L::jsonb,%L,%L,%L)','10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','missing',repeat('c',64),pg_temp.payload('30000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',(select summary from public.dataset_doctor_jobs where id='30000000-0000-4000-8000-000000000001'),'null',public.dataset_training_final_selection('30000000-0000-4000-8000-000000000001'))::text,'standard','datasets','final/a'));
create temporary table override_payload as select pg_temp.payload('30000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',j.summary,jsonb_build_object('receipt_id',r.id::text,'decision',r.decision,'contract_version',r.decision_contract_version,'warning_fingerprint',r.warning_fingerprint,'dataset_snapshot_fingerprint',r.dataset_snapshot_fingerprint),public.dataset_training_final_selection(j.id)) payload from public.dataset_doctor_jobs j cross join public.dataset_doctor_training_decision_receipts r where j.id='30000000-0000-4000-8000-000000000001' and r.decision_idempotency_key='decision-one';
create temporary table override_job as select job_id from public.submit_trainer_compute_job('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','override-one',repeat('d',64),(select payload from override_payload),'standard','datasets','final/a');
do $$begin assert (select training_job_id from public.dataset_doctor_training_decision_receipts where decision_idempotency_key='decision-one')=(select job_id from override_job);assert (select job_id from public.submit_trainer_compute_job('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','override-one',repeat('d',64),(select payload from override_payload),'standard','datasets','final/a'))=(select job_id from override_job);end$$;
alter table public.dataset_doctor_training_decision_receipts disable trigger dataset_training_decision_receipts_immutable;
update public.dataset_doctor_training_decision_receipts set warning_fingerprint=repeat('0',64) where decision_idempotency_key='decision-one';
select pg_temp.expect_error('DATASET_TRAINING_DECISION_STALE',format('select * from public.validate_dataset_training_decision_receipt(%L,%L,%L,%L)',(select receipt_id from receipt_one),'10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001'));
update public.dataset_doctor_training_decision_receipts r set warning_fingerprint=public.dataset_training_fingerprint(r.warning_snapshot) where decision_idempotency_key='decision-one';
alter table public.dataset_doctor_training_decision_receipts enable trigger dataset_training_decision_receipts_immutable;
select pg_temp.expect_error('DATASET_TRAINING_DECISION_INVALID',format('select * from public.validate_dataset_training_decision_receipt(%L,%L,%L,%L)',(select receipt_id from receipt_one),'10000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001'));
