create temporary table prompt_two as select * from public.prepare_dataset_training_decision_prompt('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','decision-two',array['40000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000002','40000000-0000-4000-8000-000000000003']::uuid[]);
create temporary table receipt_two as select * from public.record_dataset_training_decision_receipt('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','decision-two');
do $$begin assert (select receipt_id from receipt_one)<>(select receipt_id from receipt_two);end$$;
update public.compute_jobs set state='failed',terminal_at=statement_timestamp(),safe_error_code='TEST_TERMINAL',updated_at=statement_timestamp() where id=(select job_id from override_job);
select pg_temp.expect_error('DATASET_TRAINING_DECISION_INVALID',format('select * from public.submit_trainer_compute_job(%L,%L,%L,%L,%L::jsonb,%L,%L,%L)','10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','reuse-linked',repeat('e',64),(select payload from override_payload)::text,'standard','datasets','final/a'));
create temporary table override_payload_two as select pg_temp.payload('30000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',j.summary,jsonb_build_object('receipt_id',r.id::text,'decision',r.decision,'contract_version',r.decision_contract_version,'warning_fingerprint',r.warning_fingerprint,'dataset_snapshot_fingerprint',r.dataset_snapshot_fingerprint),public.dataset_training_final_selection(j.id)) payload from public.dataset_doctor_jobs j cross join public.dataset_doctor_training_decision_receipts r where j.id='30000000-0000-4000-8000-000000000001' and r.decision_idempotency_key='decision-two';
create temporary table override_job_two as select job_id from public.submit_trainer_compute_job('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','override-two',repeat('f',64),(select payload from override_payload_two),'standard','datasets','final/a');
do $$begin assert (select job_id from override_job_two)<>(select job_id from override_job);assert (select training_job_id from public.dataset_doctor_training_decision_receipts where decision_idempotency_key='decision-two')=(select job_id from override_job_two);end$$;
